('gear-assembly','Gear Assembly','Nylon',4500,'Mechanical','A precision-fit gear set printed in Nylon for wear resistance and low-friction operation. Suited for functional mechanisms and light-duty drivetrains.','{"Material":"Nylon (PA12)","Layer height":"0.16mm","Infill":"40%","Lead time":"5-7 days","Finish":"Standard"}','gear',6),
('desk-organizer','Desk Organizer','PLA+',1500,'Accessories','A modular desk tray for pens, cables, and small tools. Stackable design, printed in PLA+ for a crisp, clean finish.','{"Material":"PLA+","Layer height":"0.2mm","Infill":"15%","Lead time":"3-5 days","Finish":"Standard"}','tray',7),
